c.check();assert c.read(R/'validation.json')['passed'];z=c.load(R/'OOF.npz');ref=c.load(P/'experiments/contrast-augmentation-206/frozen-reference.npz');np.testing.assert_array_equal(z['ids'],ref['ids']);np.testing.assert_array_equal(z['last5_uniform'],ref['old_first_CNN']);y=z['y'];fold=z['fold'];qu=ref['best021']+ref['coefficient']*(z['last5_uniform']-ref['old_first_CNN']);qe=ref['best021']+ref['coefficient']*(z['update_ema']-ref['old_first_CNN']);np.testing.assert_array_equal(qu,ref['best021'])
